    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 12-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal tibia. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Amputation", "Neoadjuvant chemotherapy", "Denosumab", "Radiation therapy", "Bisphosphonates"]'::jsonb, 1, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 18-year-old female presents with pain and swelling in the distal femur. Imaging shows an eccentric, expansile, lytic metaphyseal lesion. An MRI reveals multiple fluid-fluid levels within the lesion. Histology shows blood-filled spaces lacking an endothelial lining. What is the most likely diagnosis?', '["Aneurysmal Bone Cyst (ABC)", "Unicameral Bone Cyst (UBC)", "Chondroblastoma", "Giant Cell Tumor", "Telangiectatic Osteosarcoma"]'::jsonb, 0, 'Aneurysmal bone cysts (ABCs) are expansile, blood-filled cystic lesions. The classic MRI finding is ''''fluid-fluid levels'''' representing separation of serum and red blood cells. Treatment often involves extended curettage, high-speed burring, and bone grafting.'),
    (v_topic_id, 'A 44-year-old patient presents with a slowly growing, deep, painless mass in the popliteal fossa. MRI shows a heterogeneous mass near the knee joint, but not within the joint capsule. Biopsy confirms a soft tissue sarcoma. Genetic testing reveals a t(X;18) chromosomal translocation. What is the diagnosis?', '["Clear cell sarcoma", "Liposarcoma", "Undifferentiated pleomorphic sarcoma", "Rhabdomyosarcoma", "Synovial Sarcoma"]'::jsonb, 4, 'Despite its name, Synovial Sarcoma rarely arises from the actual synovium of the joint, but typically occurs near large joints (e.g., the knee) in young adults. It is strongly associated with the t(X;18) translocation, which creates the SS18-SSX fusion gene.'),
    (v_topic_id, 'A 22-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal humerus. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Radiation therapy", "Denosumab", "Neoadjuvant chemotherapy", "Bisphosphonates", "Amputation"]'::jsonb, 2, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 75-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["A falsely negative (''cold'' or normal) bone scan", "Diffuse periosteal uptake", "Intensely increased uptake (''hot'' spots) in all lesions", "A ''superscan'' with absent renal visualization", "Increased uptake exclusively in the appendicular skeleton"]'::jsonb, 0, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'A 61-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Prostate carcinoma", "Multiple myeloma", "Malignant melanoma", "Thyroid carcinoma", "Renal cell carcinoma"]'::jsonb, 0, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 81-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal humerus. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Immediate pain relief, early mobilization, and restoration of function", "Preventing pulmonary metastasis", "Delaying surgery until radiation therapy is completed", "Curative resection of the tumor with wide margins"]'::jsonb, 1, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 16-year-old child presents with a 1-month history of fever, localized pain, and swelling over the mid-shaft of the femur. Labs show an elevated ESR and leukocytosis. Radiographs demonstrate a permeative, lytic lesion in the diaphysis with a multilamellated ''onion-skin'' periosteal reaction. Which chromosomal translocation is most characteristically associated with this diagnosis?', '["t(X;18)", "t(9;22)", "t(11;22)", "t(14;18)", "t(8;14)"]'::jsonb, 2, 'Ewing sarcoma often mimics osteomyelitis clinically (fever, elevated inflammatory markers). It occurs in the diaphysis of long bones. It is a small round blue cell tumor strongly associated with the t(11;22) translocation, resulting in the EWS-FLI1 fusion protein. CD99 is typically strongly positive.'),
    (v_topic_id, 'A 16-year-old male presents with deep, aching pain in the tibial diaphysis that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Radiofrequency ablation (RFA)", "Intravenous bisphosphonates", "Radiation therapy", "Curettage and bone grafting", "Wide surgical resection"]'::jsonb, 0, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 66-year-old patient complains of severe pain in the pelvis. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Ischemic necrosis of the medullary cavity", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Osteoblast overactivation", "Direct mechanical pressure from the tumor mass", "Deposition of amyloid protein in the bone matrix"]'::jsonb, 1, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 9-year-old patient has intense nocturnal pain in the tibia that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Open en bloc resection", "CT-guided radiofrequency ablation (RFA)", "Radiation therapy", "Intra-articular steroid injection", "Cryoablation without imaging"]'::jsonb, 1, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 66-year-old patient presents with a slowly worsening ache in the proximal humerus. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Wide surgical resection", "Denosumab therapy", "High-dose radiation therapy", "Radiofrequency ablation", "Systemic chemotherapy"]'::jsonb, 0, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 26-year-old patient presents with a slowly growing, deep, painless mass in the popliteal fossa. MRI shows a heterogeneous mass near the knee joint, but not within the joint capsule. Biopsy confirms a soft tissue sarcoma. Genetic testing reveals a t(X;18) chromosomal translocation. What is the diagnosis?', '["Liposarcoma", "Undifferentiated pleomorphic sarcoma", "Rhabdomyosarcoma", "Synovial Sarcoma", "Clear cell sarcoma"]'::jsonb, 3, 'Despite its name, Synovial Sarcoma rarely arises from the actual synovium of the joint, but typically occurs near large joints (e.g., the knee) in young adults. It is strongly associated with the t(X;18) translocation, which creates the SS18-SSX fusion gene.'),
    (v_topic_id, 'A 57-year-old patient complains of severe pain in the femur. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Ischemic necrosis of the medullary cavity", "Osteoblast overactivation", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Deposition of amyloid protein in the bone matrix", "Direct mechanical pressure from the tumor mass"]'::jsonb, 2, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 8-year-old boy falls and sustains a pathologic fracture of the proximal humerus. Radiographs show a centrally located, lytic lesion in the metaphysis that is well-marginated. A fragment of cortical bone is seen resting at the bottom of the cystic cavity. What is the most likely diagnosis?', '["Osteosarcoma", "Non-ossifying fibroma", "Unicameral (Simple) Bone Cyst", "Aneurysmal Bone Cyst", "Fibrous dysplasia"]'::jsonb, 2, 'The ''''fallen leaf'''' or ''''fallen fragment'''' sign is pathognomonic for a Unicameral Bone Cyst (UBC). When a pathologic fracture occurs, a piece of cortical bone breaks off and sinks through the serous fluid to the bottom of the cyst. An ABC would be eccentric, expansile, and contain blood.'),
    (v_topic_id, 'A 13-year-old child presents with a limp. Radiographs of the proximal femur show a ''shepherd''''s crook'' deformity with an intramedullary lesion demonstrating a ''ground-glass'' appearance. The patient also has large, irregular cafe-au-lait spots with ''coast of Maine'' borders. What other clinical feature might this patient exhibit?', '["Axillary freckling and Lisch nodules", "Precocious puberty", "Retinal hemangioblastomas", "Multiple lipomas", "Hearing loss and cranial nerve palsies"]'::jsonb, 1, 'McCune-Albright syndrome consists of the triad of polyostotic fibrous dysplasia (ground-glass bone lesions, shepherd''''s crook deformity), café-au-lait macules with irregular borders (coast of Maine), and endocrine abnormalities (most commonly precocious puberty). It is caused by an activating mutation in the GNAS gene.'),
    (v_topic_id, 'A 76-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["A falsely negative (''cold'' or normal) bone scan", "Increased uptake exclusively in the appendicular skeleton", "Diffuse periosteal uptake", "A ''superscan'' with absent renal visualization", "Intensely increased uptake (''hot'' spots) in all lesions"]'::jsonb, 0, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'An 15-year-old child sustains a minor ankle sprain. Radiographs are negative for fracture but show an incidental, 2 cm, eccentric, bubbly, cortically based radiolucent lesion with a thin sclerotic margin in the distal tibial metaphysis. The patient has no pain directly over the lesion. What is the most appropriate management?', '["Immediate core needle biopsy", "MRI of the entire tibia", "Curettage and bone grafting", "Reassurance and observation", "Prophylactic internal fixation"]'::jsonb, 3, 'This classic description is a Non-Ossifying Fibroma (NOF) or Fibrous Cortical Defect. These are asymptomatic, developmental defects seen in up to 30-40% of normal children. They invariably resolve/ossify spontaneously over time and require only observation unless they are large enough (>50% of bone diameter) to pose a risk of pathologic fracture.'),
    (v_topic_id, 'A 24-year-old patient has intense nocturnal pain in the humerus that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["CT-guided radiofrequency ablation (RFA)", "Open en bloc resection", "Intra-articular steroid injection", "Cryoablation without imaging", "Radiation therapy"]'::jsonb, 0, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 54-year-old patient complains of severe pain in the femur. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Deposition of amyloid protein in the bone matrix", "Osteoblast overactivation", "Ischemic necrosis of the medullary cavity", "Direct mechanical pressure from the tumor mass", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts."]'::jsonb, 4, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 16-year-old presents with a painless, hard bump near the knee. Radiographs show a bony outgrowth from the distal femoral metaphysis that points away from the joint. The medullary cavity of the lesion is continuous with the medullary cavity of the native bone. What is the most feared complication if this patient has multiple similar lesions?', '["Development of multiple myeloma", "Systemic metastasis to the lungs", "Malignant transformation to secondary chondrosarcoma", "Malignant transformation to osteosarcoma", "Pathologic fracture through the stalk"]'::jsonb, 2, 'This is an osteochondroma. While solitary osteochondromas have a <1% risk of malignant transformation, patients with Multiple Hereditary Exostoses (EXT1/EXT2 mutations) have a higher risk (up to 5-10%) of a lesion degenerating into a secondary chondrosarcoma. A rapidly growing or painful cartilage cap (> 2 cm in an adult) is a warning sign.'),
    (v_topic_id, 'A 85-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["Intensely increased uptake (''hot'' spots) in all lesions", "A ''superscan'' with absent renal visualization", "Diffuse periosteal uptake", "A falsely negative (''cold'' or normal) bone scan", "Increased uptake exclusively in the appendicular skeleton"]'::jsonb, 3, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'A 14-year-old patient has intense nocturnal pain in the radius that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Cryoablation without imaging", "CT-guided radiofrequency ablation (RFA)", "Radiation therapy", "Intra-articular steroid injection", "Open en bloc resection"]'::jsonb, 1, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 43-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis", "Dissect extensively through intermuscular planes to avoid muscle damage", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet", "Use a longitudinal incision placed within the planned definitive resection ellipse", "Use a transverse incision parallel to skin tension lines for a better cosmetic result"]'::jsonb, 3, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 52-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal humerus. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Immediate pain relief, early mobilization, and restoration of function", "Delaying surgery until radiation therapy is completed", "Curative resection of the tumor with wide margins", "Preventing pulmonary metastasis"]'::jsonb, 1, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 17-year-old presents with a painful, enlarging mass around the distal femur. Radiographs reveal a destructive, mixed lytic and blastic lesion in the metaphysis, with a ''sunburst'' periosteal reaction and a Codman triangle. A biopsy shows malignant cells producing unmineralized osteoid. Which of the following is the standard treatment protocol?', '["Curettage, phenol adjuvant, and cementation", "Primary radiation therapy followed by resection", "Neoadjuvant radiation and chemotherapy without surgery", "Surgical resection alone", "Neoadjuvant chemotherapy, surgical resection, and adjuvant chemotherapy"]'::jsonb, 4, 'Osteosarcoma is the most common primary bone malignancy in adolescents. It typically occurs in the metaphysis of long bones. Histologic hallmark is the production of osteoid by malignant cells. Standard treatment is neoadjuvant (preoperative) chemotherapy, wide surgical resection (limb salvage), followed by adjuvant chemotherapy based on tumor necrosis rate.'),
    (v_topic_id, 'A 72-year-old patient complains of severe pain in the femur. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Deposition of amyloid protein in the bone matrix", "Ischemic necrosis of the medullary cavity", "Direct mechanical pressure from the tumor mass", "Osteoblast overactivation", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts."]'::jsonb, 4, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 19-year-old patient presents with rapid swelling of the tibia. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Fat floating on water within a lipoma", "Separation of cellular blood components from serum", "Pus settling from an abscess", "Necrotic tumor debris", "Contrast pooling in a hemangioma"]'::jsonb, 1, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 79-year-old patient complains of severe pain in the radius. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Direct mechanical pressure from the tumor mass", "Ischemic necrosis of the medullary cavity", "Osteoblast overactivation", "Deposition of amyloid protein in the bone matrix", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts."]'::jsonb, 4, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
